-- 20260623120001 — engine_params v10: imperial-only load steps
--
-- The imperial/metric unit feature is removed; the engine records and prescribes
-- exclusively in pounds. The per-equipment `increment` / `rounding` tunables,
-- previously stored as per-unit `{kg, lb}` objects, are flattened to a single
-- pound value. This is the only change from v9 — every other tunable is identical.
--
-- Flattening `perEquipmentStep` from an object to a number changes the params
-- schema *shape*, so schema_version bumps to 5 (params-provenance.ts). This seeds
-- v10 as a fully materialized v5 snapshot with its canonical sha256 hash
-- (generated by the app's `engineParamsSchema.parse()` + `hashParams()`), so it
-- replays exactly. v9 and earlier carry the old `{kg, lb}` shape, so under schema
-- v5 their stored bytes no longer parse to a byte-complete materialization and are
-- flagged non-replayable.

-- single-active invariant: deactivate the current active version before insert.
update public.engine_params set is_active = false where is_active = true;

insert into public.engine_params (version, params, is_active, notes, schema_version, params_hash, code_sha, is_replayable)
