-- versions <= 9 carry the old per-unit {kg,lb} step shape, so under schema v5
-- their stored bytes are no longer byte-complete materializations; flag them
-- non-replayable to match what the reader (resolveProvenance) now computes.
update public.engine_params set is_replayable = false where version <= 9;
